DO $seed$
DECLARE conflicting_ids TEXT;
BEGIN
    SELECT string_agg(s.result_id, ', ' ORDER BY s.result_id)
    INTO conflicting_ids
    FROM pg_temp.temp_results_seed s
    JOIN public.results r USING (result_id)
    WHERE ROW(r.result_title, r.order_term, r.enforcement_result, r.case_result, r.case_result_type, r.active, r.order_accruing, r.requires_creditor, r.enforcement_hold, r.requires_enforcer, r.generates_hearing, r.generates_warrant, r.lists_monies, r.result_parameters::text, r.requires_employment_data, r.allow_additional_action, r.enf_next_permitted_actions, r.manual_enforcement, r.auto_enforcement) IS DISTINCT FROM ROW(s.result_title, s.order_term, s.enforcement_result, s.case_result, s.case_result_type, s.active, s.order_accruing, s.requires_creditor, s.enforcement_hold, s.requires_enforcer, s.generates_hearing, s.generates_warrant, s.lists_monies, s.result_parameters::text, s.requires_employment_data, s.allow_additional_action, s.enf_next_permitted_actions, s.manual_enforcement, s.auto_enforcement);
    IF conflicting_ids IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0001',
            MESSAGE = 'PO-10295 conflicting Results: ' || conflicting_ids;
    END IF;
END;
$seed$;
INSERT INTO public.results (result_id, result_title, order_term, enforcement_result, case_result, case_result_type, active, order_accruing, requires_creditor, enforcement_hold, requires_enforcer, generates_hearing, generates_warrant, lists_monies, result_parameters, requires_employment_data, allow_additional_action, enf_next_permitted_actions, manual_enforcement, auto_enforcement)
SELECT s.result_id, s.result_title, s.order_term, s.enforcement_result, s.case_result, s.case_result_type, s.active, s.order_accruing, s.requires_creditor, s.enforcement_hold, s.requires_enforcer, s.generates_hearing, s.generates_warrant, s.lists_monies, s.result_parameters, s.requires_employment_data, s.allow_additional_action, s.enf_next_permitted_actions, s.manual_enforcement, s.auto_enforcement
FROM pg_temp.temp_results_seed s
WHERE NOT EXISTS (SELECT 1 FROM public.results r WHERE r.result_id = s.result_id)
ORDER BY s.result_id;
DROP TABLE pg_temp.temp_results_seed;
